from collections import deque

graph = {0: [1, 2], 1: [3], 2: [3], 3: [0]}
distance = {0: 0}
queue = deque([0])
while queue:
    node = queue.popleft()
    for neighbor in graph.get(node, []):
        if neighbor not in distance:
            distance[neighbor] = distance[node] + 1  # Mark at enqueue time.
            queue.append(neighbor)
print(distance[3], len(distance))

import math

coins, amount = [1, 3, 4], 6
dp = [0] + [math.inf] * amount
for subtotal in range(1, amount + 1):
    for coin in coins:
        if coin <= subtotal:
            # Infinite predecessor remains unreachable; no invalid shortcut.
            dp[subtotal] = min(dp[subtotal], dp[subtotal - coin] + 1)
answer = dp[amount] if math.isfinite(dp[amount]) else -1
print(answer)

from collections import deque

def level_sums(root):
    if root is None:
        return []
    pending = deque([root])
    totals = []
    while pending:
        level_total = 0
        for _ in range(len(pending)):
            value, left, right = pending.popleft()
            level_total += value
            for child in (left, right):
                if child is not None:
                    pending.append(child)
        totals.append(level_total)
    return totals

tree = (4, (1, None, (3, None, None)), (7, (6, None, None), (9, None, None)))
assert level_sums(None) == []
assert level_sums((-2, None, None)) == [-2]
print(*level_sums(tree))

def peak_rooms(intervals):
    events = []
    for start, end in intervals:
        if end < start:
            raise ValueError("end before start")
        if start != end:
            events.extend([(start, 1), (end, -1)])
    active = peak = 0
    for _, change in sorted(events):
        active += change
        peak = max(peak, active)
    return peak

assert peak_rooms([(0, 3), (3, 8)]) == 1
assert peak_rooms([(2, 2)]) == 0
print(peak_rooms([(0, 4), (1, 3), (3, 7), (3, 5)]))

