from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/interview_practice/interview_lab.json").read_text(
        encoding="utf-8"
    )
)
import heapq, math

heap = []
for r in lab["catalog"]:
    if r["n"] < 10:
        continue
    key = (math.floor(r["total"] / r["n"] * 1000000000000.0 + 0.5), -r["id"])
    if len(heap) < 10:
        heapq.heappush(heap, key)
    elif key > heap[0]:
        heapq.heapreplace(heap, key)
ranked = sorted(heap, reverse=True)
result = -ranked[0][1]
print(result)

